#include <sstream>
#include <string>
#include <vector>

std::vector<std::string> wrapText(const std::string& text, int width)
{
    if (width < 1) width = 1;
    const std::size_t w{ static_cast<std::size_t>(width) };
    std::vector<std::string> out;
    std::size_t start{ 0 };
    while (true)
    {
        const std::size_t nl{ text.find('\n', start) };
        const std::string paragraph{ text.substr(start, nl == std::string::npos ? std::string::npos : nl - start) };
        std::istringstream words{ paragraph };
        std::string line;
        bool any{ false };
        for (std::string word; words >> word;)
        {
            any = true;
            while (word.size() > w)
            {
                if (!line.empty()) { out.push_back(line); line.clear(); }
                out.push_back(word.substr(0, w));
                word = word.substr(w);
            }
            if (line.empty()) line = word;
            else if (line.size() + 1 + word.size() <= w) line += " " + word;
            else { out.push_back(line); line = word; }
        }
        if (!line.empty()) out.push_back(line);
        else if (!any) out.push_back("");
        if (nl == std::string::npos) break;
        start = nl + 1;
    }
    return out;
}

unitTests:
using Lines = std::vector<std::string>;
TEST("the example") { CHECK_EQ(wrapText("Air resistance. 0 means none.", 12), (Lines{ "Air", "resistance.", "0 means", "none." })); }
TEST("fits on one line") { CHECK_EQ(wrapText("short text", 40), (Lines{ "short text" })); }
TEST("exact fit") { CHECK_EQ(wrapText("abc def", 7), (Lines{ "abc def" })); CHECK_EQ(wrapText("abc def", 6), (Lines{ "abc", "def" })); }
TEST("long words are cut") { CHECK_EQ(wrapText("a supercalifragilistic word", 8), (Lines{ "a", "supercal", "ifragili", "stic", "word" })); }
TEST("newlines and blank lines") { CHECK_EQ(wrapText("one\n\ntwo three", 20), (Lines{ "one", "", "two three" })); }
TEST("extra spaces") { CHECK_EQ(wrapText("  lots   of    space  ", 20), (Lines{ "lots of space" })); }
TEST("width zero") { CHECK_EQ(wrapText("ab", 0), (Lines{ "a", "b" })); }

